<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/PortalActionAcceptanceFixture.php';
/** Actual portal entry points deny missing explicit assignments before business projection reads. */
final class PortalShopAccessAcceptanceTest extends WP_UnitTestCase {
 private static function isAclLifecycleProofQuery(string $sql):bool {
  global $wpdb;
  foreach(DigiForge\Security\ShopAccessPolicy::canonicalShops() as $shop){
   $proof=$wpdb->prepare('SELECT event_type,actor_id,object_id,context FROM '.DigiForge\Database\Tables::audit_log()." WHERE object_type='shop_access' AND event_type IN ('shop_access_grant','shop_access_revoke') AND CASE WHEN JSON_VALID(context) THEN BINARY JSON_UNQUOTE(JSON_EXTRACT(context,'$.shop'))=BINARY %s ELSE false END ORDER BY id ASC LIMIT 1001",$shop);
   if($sql===$proof)return true;
  }
  return false;
 }
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 public function testAdministratorWithoutAssignmentCannotReadAnyShopOrGlobalBusinessCounts():void {
  $queries=[];$capture=static function(string $sql)use(&$queries):string{if(preg_match('/^\s*SELECT\b/i',$sql)&&str_contains($sql,'digiforge_')&&!str_contains($sql,'option_name')&&!self::isAclLifecycleProofQuery($sql))$queries[]=$sql;return $sql;};$get=$_GET;add_filter('query',$capture);
  try{foreach(['digital','personalized_pod','standard_pod','jewelry','all']as $shop){$_GET=['df_view'=>'orders','df_shop'=>$shop];$html=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString('explicit assignment',strtolower($html));self::assertStringNotContainsString('Recent orders',$html);}}finally{$_GET=$get;remove_filter('query',$capture);}self::assertSame([],$queries);
 }
 public function testUnauthorizedStoredReviewTargetDoesNotLoadFullEvidence():void {
  $candidate=(new DigiForge\Research\Repository())->createCandidate(['shop_key'=>'digital','title'=>'Foreign ACL source '.wp_generate_uuid4()]);self::assertNotWPError($candidate);$queries=[];$table=DigiForge\Database\Tables::research_candidates();$capture=static function(string $sql)use(&$queries,$table):string{if(str_contains($sql,'SELECT * FROM '.$table))$queries[]=$sql;return $sql;};add_filter('query',$capture);try{$result=DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_review_research',(int)$candidate['id'],'digital',['decision'=>'APPROVED']);self::assertWPError($result);self::assertSame('portal_confirmation_access',$result->get_error_code());}finally{remove_filter('query',$capture);}self::assertSame([],$queries);
 }
 public function testExplicitDigitalAssignmentShowsOnlyAuthorizedSelectorAndScopedCandidate():void {
  $owner=self::factory()->user->create(['role'=>'administrator']);$subject=get_current_user_id();$cap='manage_digiforge_research';
  ShopAccessFixture::provision([ShopAccessFixture::authority($owner,'digital',[$cap])]);self::assertNotWPError(ShopAccessFixture::grant($owner,$subject,'digital',[$cap]));
  $repo=new DigiForge\Research\Repository();$own=$repo->createCandidate(['shop_key'=>'digital','title'=>'ACL own '.wp_generate_uuid4()]);$foreign=$repo->createCandidate(['shop_key'=>'jewelry','title'=>'ACL foreign '.wp_generate_uuid4()]);self::assertNotWPError($own);self::assertNotWPError($foreign);
  $get=$_GET;try{$_GET=['df_view'=>'approvals','df_shop'=>'digital'];$html=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString($own['title'],$html);self::assertStringNotContainsString($foreign['title'],$html);self::assertStringContainsString('<option value="digital"',$html);self::assertStringNotContainsString('<option value="jewelry"',$html);self::assertStringNotContainsString('<option value="all"',$html);self::assertStringContainsString('SHOP SCOPE',$html);
   $_GET=['df_view'=>'approvals','df_shop'=>'jewelry'];$denied=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString('explicit assignment',strtolower($denied));self::assertStringNotContainsString($foreign['title'],$denied);
   $_GET=['df_view'=>'approvals','df_shop'=>'all'];self::assertStringContainsString('explicit assignment',strtolower((new DigiForge\Portal\Portal())->render()));
  }finally{$_GET=$get;}
  self::assertNotWPError(DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_review_research',(int)$own['id'],'digital',['decision'=>'APPROVED']));self::assertWPError(DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_review_research',(int)$foreign['id'],'jewelry',['decision'=>'APPROVED']));
  PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',['candidate_id'=>$own['id'],'decision'=>'APPROVED']);global $wpdb;self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.DigiForge\Database\Tables::research_candidates().' WHERE id=%d',$own['id'])));self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.DigiForge\Database\Tables::research_candidates().' WHERE id=%d',$foreign['id'])));
 }
 public function testFourExplicitAssignmentsPermitTheActualGlobalDashboard():void {
  $owner=self::factory()->user->create(['role'=>'administrator']);$subject=get_current_user_id();$shops=['digital','personalized_pod','standard_pod','jewelry'];$records=[];foreach($shops as $shop)$records[]=ShopAccessFixture::authority($owner,$shop,['manage_digiforge']);ShopAccessFixture::provision($records);foreach($shops as $shop)self::assertNotWPError(ShopAccessFixture::grant($owner,$subject,$shop,['manage_digiforge']));
  $get=$_GET;try{$_GET=['df_view'=>'dashboard','df_shop'=>'all'];$html=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString('Stage-F operator pulse',$html);foreach(array_merge(['all'],$shops)as $shop)self::assertStringContainsString('<option value="'.$shop.'"',$html);}finally{$_GET=$get;}
 }
 public function testMissingAssignmentDeniesPolicySaveBeforeReadingOrReplacingPolicy():void {
  $queries=[];$table=DigiForge\Database\Tables::shop_ai_policies();$capture=static function(string $sql)use(&$queries,$table):string{if(str_contains($sql,$table))$queries[]=$sql;return $sql;};add_filter('query',$capture);try{PortalActionAcceptanceFixture::invoke('SAVE_AI_POLICY_ACTION',['shop_key'=>'digital','currency'=>'USD','stage_develop_monthly_budget'=>'1.00'],true,false);}finally{remove_filter('query',$capture);}self::assertSame([],$queries);
 }
 public function testActualShortcodeDeniedOutputCannotAppendGlobalApprovalOrControlReads():void {
  (new DigiForge\Portal\Portal())->register();(new DigiForge\Portal\U3ApprovalInbox())->register();(new DigiForge\Portal\FrontendControls())->register();
  $queries=[];$capture=static function(string $sql)use(&$queries):string{if(preg_match('/^\s*SELECT\b/i',$sql)&&str_contains($sql,'digiforge_')&&!str_contains($sql,'option_name')&&!self::isAclLifecycleProofQuery($sql))$queries[]=$sql;return $sql;};$get=$_GET;add_filter('query',$capture);
  try{foreach(['approvals','system']as $view){$_GET=['df_view'=>$view,'df_shop'=>'digital'];$html=do_shortcode('[digiforge_admin_portal]');self::assertStringNotContainsString('df-u3-operational-approvals',$html);self::assertStringNotContainsString('df-u3-approval-inbox',$html);self::assertStringNotContainsString('Run Controlled AI Test',$html);}}finally{$_GET=$get;remove_filter('query',$capture);}self::assertSame([],$queries);
 }
 public function testActualShortcodeSelectedProductPlansExcludeForeignEvenWithFourShopGrants():void {
  ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],['manage_digiforge_research','manage_digiforge_products']);
  require_once __DIR__.'/PortalSourceWorkflowAcceptanceTest.php';$fixture=new PortalSourceWorkflowAcceptanceTest();$candidate=new ReflectionMethod($fixture,'candidate');$candidate->setAccessible(true);$product=new ReflectionMethod($fixture,'product');$product->setAccessible(true);$flows=[];$production=new DigiForge\Production\Repository();global $wpdb;
  foreach(['digital','jewelry']as $shop){$flow=$product->invoke($fixture,$candidate->invoke($fixture,$shop,'shortcode-'.$shop.'-'.wp_rand()));$plan=$production->createPlan(['product_version_id'=>$flow['version']['id'],'plan_key'=>'shortcode-plan-'.wp_rand(),'version_label'=>'synthetic','channel'=>'digital','production_type'=>'deterministic']);self::assertNotWPError($plan);self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::production_plans(),['state'=>'REVIEW_REQUIRED'],['id'=>$plan['id']]));$flows[$shop]=$flow;}
  (new DigiForge\Portal\Portal())->register();(new DigiForge\Portal\U3ApprovalInbox())->register();$get=$_GET;try{$_GET=['df_view'=>'approvals','df_shop'=>'digital'];$html=do_shortcode('[digiforge_admin_portal]');self::assertStringContainsString('df-u3-product-approvals',$html);self::assertStringContainsString($flows['digital']['product']['name'],$html);self::assertStringNotContainsString($flows['jewelry']['product']['name'],$html);self::assertStringNotContainsString('df-u3-operational-approvals',$html);}finally{$_GET=$get;}
 }
 public function testProductRejectionRequiresCurrentExplicitConfirmationBeforeRealLocalStateChanges():void {
  ShopAccessFixture::authorizeActor(get_current_user_id(),['digital'],['manage_digiforge_products','manage_digiforge_production','manage_digiforge_research']);require_once __DIR__.'/PortalSourceWorkflowAcceptanceTest.php';$fixture=new PortalSourceWorkflowAcceptanceTest();$candidate=new ReflectionMethod($fixture,'candidate');$candidate->setAccessible(true);$product=new ReflectionMethod($fixture,'product');$product->setAccessible(true);$flow=$product->invoke($fixture,$candidate->invoke($fixture,'digital','u3-confirm-'.wp_rand()));$repo=new DigiForge\Production\Repository();$plan=$repo->createPlan(['product_version_id'=>$flow['version']['id'],'plan_key'=>'u3-confirm-'.wp_rand(),'version_label'=>'synthetic','channel'=>'digital','production_type'=>'deterministic']);self::assertNotWPError($plan);$bundle=$repo->createBundle(['production_plan_id'=>$plan['id'],'bundle_key'=>'u3-confirm-'.wp_rand(),'version_label'=>'synthetic']);self::assertNotWPError($bundle);global $wpdb;foreach([DigiForge\Database\Tables::production_plans()=>$plan['id'],DigiForge\Database\Tables::release_bundles()=>$bundle['id']]as $table=>$id)self::assertSame(1,$wpdb->update($table,['state'=>'REVIEW_REQUIRED'],['id'=>$id]));
  $body=['product_version_id'=>$flow['version']['id'],'decision'=>'REJECTED'];$this->submitProductReview($body);self::assertSame('REVIEW_REQUIRED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.DigiForge\Database\Tables::production_plans().' WHERE id=%d',$plan['id'])));self::assertSame('REVIEW_REQUIRED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.DigiForge\Database\Tables::release_bundles().' WHERE id=%d',$bundle['id'])));
  (new DigiForge\Portal\Portal())->register();(new DigiForge\Portal\U3ApprovalInbox())->register();$get=$_GET;try{$_GET=['df_view'=>'approvals','df_shop'=>'digital'];$html=do_shortcode('[digiforge_admin_portal]');self::assertStringContainsString('Product version review #'.$flow['version']['id'],$html);self::assertStringContainsString('df-confirm-digiforge_u3_product_review-'.$flow['version']['id'],$html);$directory=getenv('DF_CONFIRMATION_FIXTURE_DIR');if(is_string($directory)&&is_dir($directory))self::assertSame(strlen($html),file_put_contents($directory.'/confirmation-product.html',$html));}finally{$_GET=$get;}
  $context=DigiForge\Portal\ReviewConfirmation::inspect('digiforge_u3_product_review',(int)$flow['version']['id'],'digital',['decision'=>'REJECTED']);self::assertNotWPError($context);$body+=['df_confirm_review'=>'1','df_confirmation_shop'=>'digital','df_confirmation_nonce'=>$context['confirmation_nonce'],'df_confirmation_issued_at'=>$context['issued_at'],'df_confirmation_tokens'=>['REJECTED'=>$context['token']]];$qa=$repo->addQa(['target_type'=>'plan','target_id'=>$plan['id'],'check_type'=>'confirmation_source_marker','status'=>'PENDING','details'=>['fixture'=>'Changed recorded local QA, no certified assertion']]);self::assertNotWPError($qa);$this->submitProductReview($body);self::assertSame('REVIEW_REQUIRED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.DigiForge\Database\Tables::production_plans().' WHERE id=%d',$plan['id'])));$fresh=DigiForge\Portal\ReviewConfirmation::inspect('digiforge_u3_product_review',(int)$flow['version']['id'],'digital',['decision'=>'REJECTED']);self::assertNotWPError($fresh);$body['df_confirmation_nonce']=$fresh['confirmation_nonce'];$body['df_confirmation_issued_at']=$fresh['issued_at'];$body['df_confirmation_tokens']['REJECTED']=$fresh['token'];$this->submitProductReview($body);self::assertSame('REJECTED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.DigiForge\Database\Tables::production_plans().' WHERE id=%d',$plan['id'])));self::assertSame('REJECTED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.DigiForge\Database\Tables::release_bundles().' WHERE id=%d',$bundle['id'])));
 }
 private function submitProductReview(array $body):void {
  $post=$_POST;$request=$_REQUEST;$capture=static function():never{throw new RuntimeException('u3-local-return');};add_filter('wp_redirect',$capture);try{$_POST=$_REQUEST=$body+['_wpnonce'=>wp_create_nonce('digiforge_u3_product_review')];try{(new DigiForge\Portal\U3ApprovalInbox())->register();do_action('admin_post_digiforge_u3_product_review');self::fail('Product review must return.');}catch(RuntimeException $error){self::assertSame('u3-local-return',$error->getMessage());}}finally{remove_filter('wp_redirect',$capture);$_POST=$post;$_REQUEST=$request;}
 }
 public function testForeignStoredAssetCannotLoadMetadataOrBytesThroughGenuineReviewerNonce():void {
  ShopAccessFixture::authorizeActor(get_current_user_id(),['digital'],['manage_digiforge_products','manage_digiforge_production']);require_once __DIR__.'/PortalSourceWorkflowAcceptanceTest.php';$fixture=new PortalSourceWorkflowAcceptanceTest();$candidate=new ReflectionMethod($fixture,'candidate');$candidate->setAccessible(true);$product=new ReflectionMethod($fixture,'product');$product->setAccessible(true);$flow=$product->invoke($fixture,$candidate->invoke($fixture,'jewelry','foreign-asset-'.wp_rand()));$repo=new DigiForge\Production\Repository();$spec=$repo->createSpec(['product_version_id'=>$flow['version']['id'],'asset_key'=>'foreign-asset-'.wp_rand(),'asset_type'=>'print','purpose'=>'Foreign stored private customer asset','format'=>'txt']);self::assertNotWPError($spec);$revision=$repo->addRevision(['asset_spec_id'=>$spec['id'],'revision_label'=>'foreign-private','checksum_sha256'=>hash('sha256','synthetic local fixture bytes'),'storage_reference'=>'digiforge-private/foreign-asset-fixture.txt']);self::assertNotWPError($revision);
  $queries=[];$capture=static function(string $sql)use(&$queries):string{if(str_contains($sql,'SELECT ar.*,s.asset_type'))$queries[]=$sql;return $sql;};$die=static fn()=>static function():never{throw new RuntimeException('asset-acl-denied');};$get=$_GET;$request=$_REQUEST;add_filter('query',$capture);add_filter('wp_die_handler',$die);try{$_GET=$_REQUEST=['revision_id'=>$revision['id'],'_wpnonce'=>wp_create_nonce(DigiForge\Portal\U3AssetReview::nonceAction((int)$revision['id']))];try{(new DigiForge\Portal\U3AssetReview())->serve();self::fail('Foreign asset must deny.');}catch(RuntimeException $error){self::assertSame('asset-acl-denied',$error->getMessage());}}finally{$_GET=$get;$_REQUEST=$request;remove_filter('query',$capture);remove_filter('wp_die_handler',$die);}self::assertSame([],$queries);
 }
